# area: gradual_any
# hypothesis: Injecting Any into a parameter keeps the checker gradual, so after isinstance narrowing with a swallowing with-block the join is int | Any and not a narrowed str.
from typing import Any, Literal, reveal_type


class Suppress2:
    def __enter__(self) -> None:
        return None

    def __exit__(self, exc_type: object, exc_value: object, tb: object) -> Literal[True]:
        return True


class NoSuppress2:
    def __enter__(self) -> None:
        return None

    def __exit__(self, exc_type: object, exc_value: object, tb: object) -> Literal[False]:
        return False


def suppressed(x: Any) -> None:
    if isinstance(x, int):
        with Suppress2():
            raise ValueError
    reveal_type(x)


def propagated(x: Any) -> None:
    if isinstance(x, int):
        with NoSuppress2():
            raise ValueError
    reveal_type(x)


suppressed(3)
suppressed('s')
try:
    propagated(3)
except ValueError:
    print('propagated')
print('done')
